import assert from 'node:assert/strict';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const { generateSecMsGecV2 } = require('../cloudfunctions/youversion-verse/edge-gec-v2.js');
const { EDGE_TTS, synthesizeEdgeSpeech } = require('../cloudfunctions/youversion-verse/edge-tts.js');
// Independently generated by the pinned upstream Python implementation (see NOTICE).
const vectors = [
  [0, '52BC7A17B50DFEC9-28C4394775C8751CD2F6859C030C06DB1489ACAB3B3A7651831FC26895177ED6'],
  [299, '52BC7A17B50DFEC9-28C4394775C8751CD2F6859C030C06DB1489ACAB3B3A7651831FC26895177ED6'],
  [300, 'F7535A20A262E331-28675BF85C7106BBF20035A78FCB0B6890813EAD5C3B983EF3424931B720BABB'],
  [1760000000, '6D50DDDB91812C33-DD68EFB01898B0750C9797D51A5FF93471DFDAE6888A1039D532CBDCCE54545D'],
  [1793145600, '03158245BBE62227-2757CAE86183503621AD55C86D5F60FB514515BB4CBFCF51885941278774BE2F'],
  [1793145899, '03158245BBE62227-2757CAE86183503621AD55C86D5F60FB514515BB4CBFCF51885941278774BE2F'],
  [1793145900, '591F5CED44B68104-E6723B0ED135AFA218EB92F7EB33419A88E00062D99ADE0162F5E817AC2567BD'],
];
for (const [seconds, expected] of vectors) {
  assert.equal(generateSecMsGecV2(seconds * 1000, EDGE_TTS.trustedClientToken), expected);
}
assert.equal(EDGE_TTS.voice, 'zh-CN-YunyangNeural');
assert.equal(EDGE_TTS.secMsGecVersion, '2-143.0.3650.75');
console.log('PASS: seven upstream v2 vectors, five-minute boundary and male voice');

// Exercise the real handshake and frame parser without depending on network timing.
const { EventEmitter } = await import('node:events');
const { readFileSync } = await import('node:fs');
const { runInNewContext } = await import('node:vm');
const crypto = require('node:crypto');
const source = readFileSync(new URL('../cloudfunctions/youversion-verse/edge-tts.js', import.meta.url), 'utf8');
const serverDate = new Date('2026-10-28T12:02:00Z');
function mockedClient(responses) {
  const requests = [], sent = [];
  const https = { request(options) {
    requests.push(options);
    const request = new EventEmitter();
    request.destroy = () => {};
    request.end = () => queueMicrotask(() => {
      const response = responses.shift();
      if (response !== 'audio' && response !== 'empty' && response !== 'bad-accept') {
        request.emit('response', { statusCode: response, headers: { date: serverDate.toUTCString() } });
        return;
      }
      const socket = new EventEmitter();
      socket.destroy = () => {};
      socket.write = frame => {
        const lengthType = frame[1] & 127;
        const offset = lengthType < 126 ? 2 : lengthType === 126 ? 4 : 10;
        const data = Buffer.from(frame.subarray(offset + 4));
        for (let i = 0; i < data.length; i++) data[i] ^= frame[offset + i % 4];
        sent.push(data.toString());
      };
      const accept = crypto.createHash('sha1').update(options.headers['Sec-WebSocket-Key'] + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');
      request.emit('upgrade', { headers: { 'sec-websocket-accept': response === 'bad-accept' ? 'invalid' : accept } }, socket, Buffer.alloc(0));
      if (response === 'bad-accept') return;
      const frame = (opcode, data) => Buffer.concat([Buffer.from([0x80 | opcode, data.length]), data]);
      const header = Buffer.from('Path:audio\r\n');
      const audio = Buffer.concat([Buffer.from([0, header.length]), header, Buffer.from([0xff, 0xf3, 0x44, 0])]);
      const frames = Buffer.concat([
        ...(response === 'audio' ? [frame(2, audio)] : []),
        frame(1, Buffer.from('Path:turn.end\r\n\r\n')),
      ]);
      // TCP data is allowed to split inside a frame header or audio payload.
      socket.emit('data', frames.subarray(0, 3));
      socket.emit('data', frames.subarray(3));
    });
    return request;
  } };
  const module = { exports: {} };
  runInNewContext(source, { module, Buffer, URLSearchParams, setTimeout, clearTimeout,
    require: name => name === 'https' ? https : name === './edge-gec-v2' ? { generateSecMsGecV2 } : require(name),
  });
  return { ...module.exports, requests, sent };
}
const client = mockedClient([403, 'audio']);
assert.deepEqual(await client.synthesizeEdgeSpeech('甲<&乙'), Buffer.from([0xff, 0xf3, 0x44, 0]));
assert.equal(client.requests.length, 2);
for (const request of client.requests) {
  assert.equal(request.hostname, 'speech.platform.bing.com');
  const url = new URL(request.path, `https://${request.hostname}`);
  assert.equal(url.pathname, '/consumer/speech/synthesize/readaloud/edge/v1');
  assert.equal(url.searchParams.get('TrustedClientToken'), EDGE_TTS.trustedClientToken);
  assert.equal(url.searchParams.get('Sec-MS-GEC-Version'), EDGE_TTS.secMsGecVersion);
  assert.match(url.searchParams.get('Sec-MS-GEC'), /^[A-F0-9]{16}-[A-F0-9]{64}$/);
}
assert.equal(new URL(client.requests[1].path, 'https://example.com').searchParams.get('Sec-MS-GEC'), generateSecMsGecV2(serverDate.getTime(), EDGE_TTS.trustedClientToken));
assert.ok(client.sent.some(message => message.includes("voice name='zh-CN-YunyangNeural'") && message.includes('甲&lt;&amp;乙')));
await assert.rejects(mockedClient([200]).synthesizeEdgeSpeech('甲'), /upgrade failed: 200/);
await assert.rejects(mockedClient([403, 403]).synthesizeEdgeSpeech('甲'), /upgrade failed: 403/);
await assert.rejects(mockedClient(['empty']).synthesizeEdgeSpeech('甲'), /returned no audio/);
await assert.rejects(mockedClient(['bad-accept']).synthesizeEdgeSpeech('甲'), /validation failed/);
console.log('PASS: v2 endpoint, clock-skew retry, fragmented audio, SSML escaping and failure handling');

if (process.argv.includes('--live')) {
  const audio = await synthesizeEdgeSpeech('起初，神创造天地。神说，要有光，就有了光。');
  assert.ok(audio.length > 1000, 'must return real audio, not an error body');
  assert.ok(audio[0] === 0xff && (audio[1] & 0xe0) === 0xe0, 'MP3 frame sync');
  const { writeFile } = await import('node:fs/promises');
  await writeFile(new URL('../.private/yunyang-protocol-check.mp3', import.meta.url), audio);
  console.log(`PASS: live ${EDGE_TTS.voice}, ${audio.length} MP3 bytes`);
}
